// Источник: web-тест .qa/e2e/tests/prayer-mode/pm-03-switch-mid-prayer-keeps-position.spec.ts, план .qa/e2e/specs/prayer-mode.md, кейс .qa/tests/prayer-mode/PM-03-switch-mid-prayer.md
// Тикет #6a86f7e7. Опора: F-103 AC2 · S-17. Проверка «нет ошибок в консоли» (page.on('console')) в приложении не переносится.
import { expect, $, driver } from '@wdio/globals';
import { pageCounter, expectVisibleText } from '../../helpers/ui.ts';
import { openPrayer, goToPage } from '../../helpers/nav.ts';
import { toHome } from '../../helpers/app.ts';

const TOTAL = 8;

function radio(name: string) {
  return driver.isAndroid
    ? $(`//*[@checkable="true" and (@content-desc="${name}" or .//*[@text="${name}"])]`)
    : $(`-ios predicate string:label == "${name}" OR name == "${name}"`);
}
async function isChecked(name: string) {
  const el = await radio(name);
  if (driver.isAndroid) return (await el.getAttribute('checked')) === 'true';
  const v = await el.getAttribute('value');
  return v === '1' || v === 'checked' || (await el.isSelected());
}
async function select(name: string, other: string) {
  await (await radio(name)).click();
  await driver.waitUntil(async () => (await isChecked(name)) && !(await isChecked(other)), { timeoutMsg: `Не выбран «${name}»` });
}
/** Тексты всех элементов экрана (Android — text, iOS — label) из дерева элементов. */
async function screenText(): Promise<string> {
  const src = await driver.getPageSource();
  const attr = driver.isAndroid ? 'text' : 'label';
  return [...src.matchAll(new RegExp(`\\s${attr}="([^"]*)"`, 'g'))].map((m) => m[1]).filter(Boolean).join('\n');
}

describe('Режим молитвы «יחיד / מניין»', () => {
  afterEach(async () => { await toHome(); });

  it('PM-03 Смена режима посреди молитвы не сбрасывает позицию #6a86f7e7 @prod-safe', async () => {
    // 1. מנחה (אשכנזי) «4 מתוך 8»; запомнить тексты секции.
    await openPrayer('mincha_ashkenaz', 'מנחה');
    await expectVisibleText('מנחה (אשכנזי)');
    await goToPage(4, TOTAL);
    expect(await pageCounter()).toBe(`4 מתוך ${TOTAL}`);
    const textBefore = await screenText();

    // 2. «מניין», затем «יחיד» — счётчик и текст прежние.
    await select('מניין', 'יחיד');
    await select('יחיד', 'מניין');
    expect(await pageCounter()).toBe(`4 מתוך ${TOTAL}`);
    expect(await screenText()).toBe(textBefore);

    // 3. 8 переключений подряд (מניין/יחיד поочерёдно), дожидаясь состояния после каждого.
    for (let i = 0; i < 8; i++) {
      if (i % 2 === 0) await select('מניין', 'יחיד');
      else await select('יחיד', 'מניין');
    }
    expect(await pageCounter()).toBe(`4 מתוך ${TOTAL}`);
    expect(await screenText()).toBe(textBefore);

    // Режим после 8 переключений — «יחיד» (возвращён).
    expect(await isChecked('יחיד')).toBe(true);
  });
});
